import unicodedata

def slugify(s):
    s = s.lower()
    s = unicodedata.normalize('NFD', s)
    s = s.encode('ascii', 'ignore').decode('ascii')
    s = ''.join(ch if ch.isalnum() else '-' for ch in s)
    while '--' in s:
        s = s.replace('--', '-')
    return s.strip('-')

